window.RP_SESSION={"id":"S-5a8545dd8e4c","messages":[{"id":"Plane-0002328","time":"2026-09-25T22:57:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"토르번은, 집무실에서 사각사각...\n\n펜을 끄적거리고 있습니다.","characters":["P-7ba611cf90be"]},{"id":"Plane-0002329","time":"2026-09-25T22:58:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"창 밖으로는 가득 찬 달이 구름에 가려진 채 어스름하게 빛나고 있었고....","characters":["P-7ba611cf90be"]},{"id":"Plane-0002330","time":"2026-09-25T22:58:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"계절이 바뀐 듯 스산해지기 시작한 바람이 잔잔하게 불어오고 있습니다.","characters":["P-7ba611cf90be"]},{"id":"Plane-0002331","time":"2026-09-25T22:59:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"양초 불빛 아래 웅크리고 앉아서는...","characters":["P-7ba611cf90be"]},{"id":"Plane-0002332","time":"2026-09-25T23:00:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"[존엄한 사자회에게.]","characters":["P-7ba611cf90be"]},{"id":"Plane-0002333","time":"2026-09-25T23:08:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"[어설픈 용맹의 공격대장, 토르번 팔켄하인이 인사를 전합니다.\n\n우리 길드는 오랜 기간 사자회와 여러 인연을 맺어왔으며, 그 과정에서 서로의 영역과 뜻을 존중하며 관계를 이어왔습니다.\n\n이에 어설픈 용맹의 부길드장 스텔라의 명을 받아, 양측의 관계와 앞으로의 협력에 관하여 이야기를 나누고자 합니다.\n\n최근 사자회와 직접 뜻을 나눌 기회가 없었기에, 이번 기회에 서로의 입장과 향후 나아갈 방향을 확인할 수 있기를 바랍니다.\n\n저, 토르번 팔켄하인은 스텔라 길드장 대리의 정식 전갈을 품고 어설픈 용맹의 사절단으로써 귀회를 직접 방문하여 친선 회담을 가지기를 희망합니다. 장소와 날짜는 사자회가 편한 쪽으로 정해도 좋습니다.\n\n사자회의 번영과 맹렬한 기상을 기원하며, 회신을 기다리겠습니다.\n\n어설픈 용맹 공격대장, 토르번 팔켄하인 올림.]","characters":["P-7ba611cf90be"]},{"id":"Plane-0002334","time":"2026-09-25T23:09:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"이런 걸 쓰게 될 줄은 몰랐는데...\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002335","time":"2026-09-25T23:11:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"좀 더 공격적으로 적어야하나... 좀 더 흥미를 이끌만한 걸 써야하나....\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002336","time":"2026-09-25T23:15:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"구색은 괜찮은데 조금 내용이 부족한 것은 맞네요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002337","time":"2026-09-25T23:15:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 좀 더 긴박한 주제를 꺼낼 필요가 있을 것 같아요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002338","time":"2026-09-25T23:16:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저도 마땅히 떠오르는 것이 없네요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002339","time":"2026-09-25T23:16:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...무력적 보증은 어떤가?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002340","time":"2026-09-25T23:16:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...책임지기 더 어려워지겠지?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002341","time":"2026-09-25T23:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 당장 서신에서 만날 날짜를 정하지 않고 있어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002342","time":"2026-09-25T23:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"이러면 한달 뒤에나 시간을 내줄지도 몰라요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002343","time":"2026-09-25T23:18:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"이야기만 보면 요즘 잘 지내? 얼굴 한번 보자. 언제 만날래?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002344","time":"2026-09-25T23:18:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"이런 느낌이니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002345","time":"2026-09-25T23:18:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"날짜를 우리가 정하면, 재촉하는 그림이 되지 않겠나? 그들이 원하는 무언가가 있다면 알아서 빠른 시일 내로 잡아줄 것 같은데.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002346","time":"2026-09-25T23:19:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"생각보다 길드간의 행정이라는게 그렇지 않아요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002347","time":"2026-09-25T23:19:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 만남을 주선한다고 하면. 무슨 목적인지 사전 조사를 하는데 최소 삼일은 들걸요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002348","time":"2026-09-25T23:19:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"심지어... 바키르와 관련되어 있을지도 모르니까 내부적으로 입단속같은 것들을 할지도 몰라요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002349","time":"2026-09-25T23:20:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그 기간도 짧지는 않을테고요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002350","time":"2026-09-25T23:20:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그런 이유에서 어렵다는거에요. 재촉하지만 바키르와 상관 없는. 어설픈 용맹과 사자회가 맞물릴만한 우려가 되는 사건.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002351","time":"2026-09-25T23:20:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그런게 필요해요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002352","time":"2026-09-25T23:21:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"사실 정말 필요한 게 있다면... 재촉 따위는 아무 연관 없겠지.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002353","time":"2026-09-25T23:21:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"결국은 명분이니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002354","time":"2026-09-25T23:21:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"이 결정으로 단순히 바키르의 정보를 얻는 것 뿐만이 아니라 장기적으로 사자회와의 관계가 어떻게 될지도 충분히 고려해보아야 한다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002355","time":"2026-09-25T23:22:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"어설프게 수작질을 쳤다간...\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002356","time":"2026-09-25T23:22:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그러다가 시간 다 놓칠걸요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002357","time":"2026-09-25T23:22:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"제가 준 기간을 생각해봐요. 그 안에 할 수 있겠어요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002358","time":"2026-09-25T23:26:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"사흘은 인원 모집에 준 기간 아닌가? 사흘 안에 회신까지 받는 건 택도 없다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002359","time":"2026-09-25T23:26:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"급한 사항인 건 알지만 좀 진정하게나. 단기적으로 볼 일이 아니지 않은가.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002360","time":"2026-09-25T23:27:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"인원 모집만으로 사흘을 사용하려고 했어요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002361","time":"2026-09-25T23:27:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그건 좀 실망인데요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002362","time":"2026-09-25T23:28:00+09:00","room":"Plane","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"눈돌아간 스텔라 무섭다","characters":[]},{"id":"Plane-0002363","time":"2026-09-25T23:28:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그럼 사흘 안에 결과를 내놓으려면 서신도 안 보내고 우리가 당장 출발해야한다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002364","time":"2026-09-25T23:28:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 사람을 부리는 법을 알려줄게요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002365","time":"2026-09-25T23:29:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"첫째, 조금 무리다 싶은 기간을 먼저 제시할 것.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002366","time":"2026-09-25T23:34:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그리고 지켜보는거죠. 어떻게 일을 해나가는지.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002367","time":"2026-09-25T23:34:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"토르번. 짧은 기간이지만 포기하지 않고 할 일을 하고 있었죠?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002368","time":"2026-09-25T23:34:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"뭘 하고 있었어요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002369","time":"2026-09-25T23:36:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...사람을 모으고, 교통편을 수배하고, 서신을 쓰면서 사자회가 혹할 미끼로 몇가지 안을 짜봤다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002370","time":"2026-09-25T23:36:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"좋아요. 일단 교통만해도 한달에 가까운 시간이 걸리는 것은 확인했잖아요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002371","time":"2026-09-25T23:37:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그러면 저에게 와서 따져야 했어요. 이게 말이 되는 시간이냐! 하고 말이죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002372","time":"2026-09-25T23:38:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...알면서도 부조리한 지시를 내리다니 뭔가 생각이 있겠지 하고 있었다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002373","time":"2026-09-25T23:39:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그것도 방법이기는 하지만...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002374","time":"2026-09-25T23:39:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"이왕이면 판단이 서면 바로 와서 이야기 해주면 좋겠어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002375","time":"2026-09-25T23:39:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저번에 에스텔과 토르번이 왔을 때처럼.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002376","time":"2026-09-25T23:39:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저도 항상 옳은 것은 아니니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002377","time":"2026-09-25T23:40:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그리고 사흘이라는 시간을 준 이유가 하나 더 있어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002378","time":"2026-09-25T23:40:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아니, 둘이라고 하죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002379","time":"2026-09-25T23:40:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"끄응... 알겠네.\"\n\n\"사흘은 어떤 이유인가...?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002380","time":"2026-09-25T23:41:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 골기아 내부에서 할 수 있는 것에 대한 시간이라면 이 정도면 충분하다고 생각한게 첫번째 이야기.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002381","time":"2026-09-25T23:41:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"두번째는, 그냥 뭐... 저도 그 때 감정이 좀 격했어가지고...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002382","time":"2026-09-25T23:41:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"미안해요. 심술이에요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002383","time":"2026-09-25T23:41:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-7ba611cf90be"]},{"id":"Plane-0002384","time":"2026-09-25T23:42:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...아무튼... 다시 원래의 이야기로 돌아오자면... 미끼를 던져볼까? 구라를 섞어서라도.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002385","time":"2026-09-25T23:42:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저는 차라리 전령 형식으로 가는게 좋지 않을까 싶어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002386","time":"2026-09-25T23:43:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"급하게 전달해야 할 일이 있다는 식으로요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002387","time":"2026-09-25T23:43:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그렇다면 내용은 있기는 해야지.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002388","time":"2026-09-25T23:43:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"토르번도 말했지만 서신이 갔다가 오고 다시 저희가 출발하는 시간까지 하기는 시간이 많이 걸리니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002389","time":"2026-09-25T23:43:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그 부분은... 계속 고민해야죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002390","time":"2026-09-25T23:44:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저도 지금 머리 짜매고 있다고요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002391","time":"2026-09-25T23:44:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"거짓말을 하는 것은 좋지만...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002392","time":"2026-09-25T23:44:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단 후순위로 미룬다는 생각이에요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002393","time":"2026-09-25T23:44:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아, 아니면 말해봐요. 좋은 핑계가 있는지.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002394","time":"2026-09-25T23:44:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그럼 책임이 무거워지겠지만 우리가 해줄 수 있는 것을 제시해야지.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002395","time":"2026-09-25T23:45:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"진짜 내키지는 않는 것인데... 무력적 보증은?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002396","time":"2026-09-25T23:45:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아까부터 무력적 보증을 이야기 하던데 뭘 하려는거에요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002397","time":"2026-09-25T23:46:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"스텔라 양은 사자회 내부에서 어떤 일이 있을 거라고 생각하는가?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002398","time":"2026-09-25T23:46:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"정말로 예상이 가지를 않아요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002399","time":"2026-09-25T23:47:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"알게된 것은 골기아 왕가에서도 주도면밀하게 살피고 있다는 것 정도에요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002400","time":"2026-09-25T23:47:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"정보를 알아보려다가 반대로 되물어졌다니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002401","time":"2026-09-25T23:49:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"바키르 경과의 연락이 끊기고, 골기아 왕가에서 정보 수집을 시작하고.\"\n\n\"이건 가설인데 말일세. 대대적인 인원 물갈이가 있었을 거라고 생각한다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002402","time":"2026-09-25T23:50:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"급진파가 강세를 가지기 시작했다면...\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002403","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"젊은 층의 급진파들이 예전부터 논란이 있기는 했지만...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002404","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"하아...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002405","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"너무 극단적으로 비약했나?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002406","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아니기만을 빌어야죠. 아뇨, 솔직히 가능성은 있어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002407","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아니면...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002408","time":"2026-09-25T23:51:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그냥 단순무식하게 해볼까요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002409","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"단순 무식?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002410","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"사자회는 전사들로 대부분 이뤄져 있어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002411","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그냥 찾아가서 강한 전사와 겨뤄보기 위해서 갔다고 해보죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002412","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"는 별로겠죠?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002413","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"하아... 머리야.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002414","time":"2026-09-25T23:52:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그거 진짜 제정신 아닌 걸로 보이는군.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002415","time":"2026-09-25T23:53:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아, 그나저나 무력적 보증은 뭘 말하는거에요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002416","time":"2026-09-25T23:54:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"물갈이가 숙청의 형태를 띄던, 인사 이동의 형태를 띄던, 인력적으로 많이 부족하지 않겠나?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002417","time":"2026-09-25T23:54:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일손이 되어준다는 말이에요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002418","time":"2026-09-25T23:54:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"간단한 이야기일세. 혼란스러운 동안 외부활동에 힘을 빌려주며 시간을 벌어주는 걸로 동맹을 강화하자는 걸세.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002419","time":"2026-09-25T23:55:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"별로 좋은 생각은 아닐 것 같아요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002420","time":"2026-09-25T23:55:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"내부의 일을 꽁꽁 숨기는 것 같은데... 대뜸 와서 그런말을 한다는 것은 경계를 살 것 같네요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002421","time":"2026-09-25T23:56:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"바키르 경을 통해 연락하던 것은 가설이 아닌 진실이지 않은가.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002422","time":"2026-09-25T23:56:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"연락이 대뜸 끊겨버린 이상, 너무 모르는 척을 하는 것도 수상해보인다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002423","time":"2026-09-25T23:56:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그것도 맞죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002424","time":"2026-09-25T23:57:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002425","time":"2026-09-25T23:57:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아니면...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002426","time":"2026-09-25T23:57:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"토르번의 단독행동으로 위장하는건 어떤가요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002427","time":"2026-09-25T23:57:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...음... 내용은?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002428","time":"2026-09-25T23:58:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"앞서 이야기한 것들을 모두 섞어봐요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002429","time":"2026-09-25T23:58:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"토르번 팔켄하인은 어설픈 용맹의 공대장이자 강한 전사와 겨루는 것을 좋아하는 인물이다.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002430","time":"2026-09-25T23:58:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"바키르의 소식이 끊인 것이 사자회의 용맹한 전사들과 겨루기 좋은 핑계라고 생각해서.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002431","time":"2026-09-25T23:58:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"동료를 이끌고 사자회로 떠났다.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002432","time":"2026-09-25T23:58:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"는 미안해요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002433","time":"2026-09-25T23:59:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그냥 무책임한 떠넘기기에요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002434","time":"2026-09-25T23:59:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"좋은 방법이 없으련지...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002435","time":"2026-09-26T00:01:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...단순히 솔직하게 말할까? 바키르의 안부 확인 차, 사자회와 친목도모를 하고 싶다?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002436","time":"2026-09-26T00:02:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그게 가장 맞기는 하죠. 솔직히 말해서...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002437","time":"2026-09-26T00:02:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"골기아 왕가에도 그렇게 먼저 조사를 해보겠다고 서신을 주기도 쉽고요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002438","time":"2026-09-26T00:03:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"허나 그들이 정말 복잡한 상황이고 폐쇄적으로 나오려 한다면...\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002439","time":"2026-09-26T00:03:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"역시 이끌어낼 수단이 필요하다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002440","time":"2026-09-26T00:04:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"이건... 역시 블러핑을 할 수 밖에 없다고 본다네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002441","time":"2026-09-26T00:04:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"어떤 블러핑이요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002442","time":"2026-09-26T00:06:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"비밀스러운.... 흠.\"\n\n\"길드관리국에서 새로운 '지침'을 준비중이다라는 비밀스러운 정보라던가.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002443","time":"2026-09-26T00:06:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그걸 저희가 사자회에 갑자기요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002444","time":"2026-09-26T00:06:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002445","time":"2026-09-26T00:06:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"아, 미안해요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002446","time":"2026-09-26T00:07:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"이게 계속 뭔가 부정만 하는 것 같아서...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002447","time":"2026-09-26T00:07:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"곰곰히 생각을 해봤는데. 당장 가장 큰 문제는...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002448","time":"2026-09-26T00:07:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저희가 사자회에 너무 아는 것이 없다는게 문제라고 생각해요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002449","time":"2026-09-26T00:07:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"어쩌면 전령이라는 핑계로 들어가서 편지를 전달한 후, 답신을 받을 때까지 사자회에서 지내도 되냐고 하는 것은 어떤가요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002450","time":"2026-09-26T00:08:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"뭔가 알아서 논의가 필요하다면 다시 돌아와서 대화를 하면 될 것이고.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002451","time":"2026-09-26T00:08:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"음. 그럼 서신의 내용은 바키르의 안부 차 평범한 이야기를 담아도 되겠군.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002452","time":"2026-09-26T00:09:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"한 번만에 회담까지 노리기엔 아무래도 확실히 너무 정보가 부족하지.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002453","time":"2026-09-26T00:09:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"네, 그 쪽에서도 회의를 하고 정해야할 내용을 추가로 담아주는게 좋을 것 같아요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002454","time":"2026-09-26T00:09:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그럼 자네의 이름으로 써야겠군.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002455","time":"2026-09-26T00:10:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그게 맞겠죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002456","time":"2026-09-26T00:10:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"제가 보내는게 맞아요. 국가는 아니지만 준 국가에 보내는 서신이니까요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002457","time":"2026-09-26T00:11:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...알겠네. 그럼 바로 교통편을 수배할테니, 서신을 준비해주겠나?\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002458","time":"2026-09-26T00:11:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"네. 알았어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002459","time":"2026-09-26T00:12:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그래도 이런 일은 처음인데 나름 잘 해낸 것 같네요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002460","time":"2026-09-26T00:13:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"삽질 좀 했지만.\"\n\n그는 자신이 적은 서신은 돌돌 말아 옆으로 치웠습니다.","characters":["P-7ba611cf90be"]},{"id":"Plane-0002461","time":"2026-09-26T00:14:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"삽질도 좀 해봐야 느는거죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002462","time":"2026-09-26T00:14:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"부딪히지 않으면 이런 일이 또 생기면 어떻게 하겠어요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002463","time":"2026-09-26T00:15:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"어휴. 사흘이라고 해서 골머리 좀 썩었다고.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002464","time":"2026-09-26T00:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"토르번도 사용해봐요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002465","time":"2026-09-26T00:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"사람 굴리기 편해요. 욕은 뒤에서 좀 먹겠지만.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002466","time":"2026-09-26T00:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"책임자가 다 그런 것 아니겠어요?\"","characters":["P-e6655a038328"]},{"id":"Plane-0002467","time":"2026-09-26T00:17:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"일단, 서쪽으로 떠날 준비를 해주시고. 서신은 내일 아침까지 제가 드릴게요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002468","time":"2026-09-26T00:18:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"알겠네. 일행들에게도 전달해놓겠네.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002469","time":"2026-09-26T00:18:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"조금만 더 고생하자고.\"","characters":["P-7ba611cf90be"]},{"id":"Plane-0002470","time":"2026-09-26T00:18:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"저야... 뭐...\"","characters":["P-e6655a038328"]},{"id":"Plane-0002471","time":"2026-09-26T00:18:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"고생이랄게 있나요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002472","time":"2026-09-26T00:18:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"그저 여기서 여러분들을 기다리는거죠.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002473","time":"2026-09-26T00:19:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"좋은 소식. 성한 몸 가지고요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002474","time":"2026-09-26T00:21:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"\"나가볼게요. 또 말할게 있으면 찾아와요.\"","characters":["P-e6655a038328"]},{"id":"Plane-0002475","time":"2026-09-26T00:21:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"스텔라는 토르번의 사무실에서 나가 방 문을 닫습니다.","characters":["P-e6655a038328"]},{"id":"Plane-0002476","time":"2026-09-26T00:22:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"토르번은 그제서야 담배 하나를 꼬나물었습니다.","characters":["P-7ba611cf90be"]},{"id":"Plane-0002477","time":"2026-09-26T00:22:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"것 참, 뒤지게 힘드네.","characters":["P-7ba611cf90be"]},{"id":"Plane-0002478","time":"2026-09-26T00:22:00+09:00","room":"Plane","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"Plane-0002479","time":"2026-09-26T00:23:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"스텔라는 방으로 들어와서 서신을 적습니다.","characters":["P-e6655a038328"]},{"id":"Plane-0002480","time":"2026-09-26T00:36:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"용맹한 전사들, 사자회 여러분께.\n\n 어설픈 용맹의 부길드장이자 길드장 대리를 담당하고 있는 스텔라 스타라이트가 안부를 전합니다.\n\n 우선 오랜기간 저희와 좋은 관계를 가져온 사자회에게 찬란한 앞길이 있기를 기원합니다.\n\n 이렇게 서신을 보낸 이유는, 오랜 기간동안 양측의 연락을 이어주던 바키르 경의 소식이 없어서 그렇습니다.\n\n 제법 오랜 기간동안 연락이 없었으나 사소한 사정이 있으리라 생각해 기다렸습니다. 하지만 평소의 바키르 경의 행보를 생각할 때 이렇게 오랜 기간동안 연락이 없던 것에 마음이 걸렸습니다.\n\n 사자회 내부의 사정 때문에 연락이 어려운 것이라면 저희가 이렇게 편지를 보내는 것이 결례라는 것을 알고 있습니다. 다만, 오랜 벗의 안부를 걱정하는 것을 허락해 주시면 감사하겠습니다.\n\n 어설픈 용맹은 그간 사자회와 많은 일을 함께 하면서 서로의 이름과 명예를 드높이는 좋은 관계로 지내왔습니다. 다만, 바키르 경의 소식이 끊기자마자 이렇게 서로의 소식이 멀어지는 것을 보고","characters":["P-e6655a038328"]},{"id":"Plane-0002481","time":"2026-09-26T00:37:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"스텔라는 편지를 같은 내용으로 필사한 뒤에 원본의 편지를 편지 봉투에 넣고. 밀랍 인장을 찍었습니다.","characters":["P-e6655a038328"]},{"id":"Plane-0002482","time":"2026-09-26T00:37:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"그리고 아마 내일 이른 아침. 토르번에게 편지 사본과 전달할 편지를 전했을 것입니다.","characters":["P-e6655a038328"]},{"id":"Plane-0002483","time":"2026-09-26T00:37:00+09:00","room":"Plane","name":"스텔라 스타라이트","profile":"라이아흐 미샤","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328"]}]};
